insert into public.site_content (locale, data) values
  ('fr', $json${"meta":{"title":"Dr Maliki Djandjieme — Ingénieur conseil en géotechnique & infrastructures","description":"Ingénieur conseil en géotechnique et infrastructures (PhD, Yokohama). Études de sol, fondations, routes, barrages et suivi de chantier pour maîtres d'ouvrage, bureaux d'études et bailleurs en Afrique de l'Ouest.","keywords":["ingénieur géotechnicien","étude géotechnique","fondations","routes","barrages","contrôle qualité","assistance à maîtrise d'ouvrage","Côte d'Ivoire","Togo","Burkina Faso"]},"nav":{"items":[{"id":"home","label":"Accueil"},{"id":"about","label":"À propos"},{"id":"services","label":"Services"},{"id":"projects","label":"Références"},{"id":"experience","label":"Parcours"},{"id":"education","label":"Formation"},{"id":"research","label":"Recherche"},{"id":"contact","label":"Contact"}],"openMenu":"Ouvrir le menu","closeMenu":"Fermer le menu","toggleTheme":"Changer de thème","language":"Langue","skip":"Aller au contenu","menuContactTitle":"Un projet d'infrastructure en tête ?","menuContactText":"Étude de sol, fondations, routes ou barrages : parlons de votre projet.","follow":"Me suivre"},"hero":{"kicker":"Ingénieur conseil · Géotechnique & Infrastructures","headline":"Des infrastructures solides, dès le sol.","name":"Dr Maliki Djandjieme","role":"docteur en géotechnique.","intro":"J'accompagne maîtres d'ouvrage, bureaux d'études et bailleurs dans la conception, le contrôle et la réalisation de routes, barrages et fondations en Afrique de l'Ouest.","badge":"Disponible pour de nouvelles missions","cta":"Discuter de votre projet","cv":"Télécharger le CV","photoAlt":"Portrait du Dr Maliki Djandjieme à son bureau","cardTitle":"PhD · Yokohama","cardText":"Consultant JICA","proof":[{"value":"8+","label":"ans d'expérience"},{"value":"4 000 km","label":"de routes suivies"},{"value":"3","label":"pays d'intervention"},{"value":"JICA","label":"consultant infrastructures"}]},"partnersLabel":"Institutions et partenaires","about":{"title":"À propos","text":"Ingénieur civil spécialisé en géotechnique, je sécurise vos projets dès la phase d'étude : un sol bien compris, ce sont des ouvrages plus sûrs, des coûts maîtrisés et moins d'imprévus sur le chantier.","yearsValue":"8+","yearsLabel":"Années d'expérience","statement":"Du laboratoire au chantier, je combine rigueur scientifique et pragmatisme de terrain pour livrer des solutions fiables, économiques et adaptées aux matériaux locaux.","cta":"Discuter de votre projet","cv":"Télécharger le CV","photoAlt":"Maliki Djandjieme en extérieur, tenant son diplôme","portraitAlt":"Portrait de Maliki Djandjieme","stats":[{"value":"4","label":"pays d'expérience"},{"value":"FR · EN · JA","label":"langues de travail"},{"value":"UEMOA","label":"coordination régionale"}]},"services":{"kicker":"Services","lead":"Des solutions fiables, économiques et adaptées au terrain.","text":"Une offre complète pour sécuriser vos projets, de l'étude de sol à la réception des travaux.","title":"Services.","items":[{"icon":1,"title":"Études géotechniques","description":"Campagnes de reconnaissance, essais en laboratoire et in situ, rapports de sol et recommandations de conception.","tags":["Sondages","Essais labo","Rapports"]},{"icon":3,"title":"Fondations & terrassements","description":"Dimensionnement des fondations, stabilité des talus et traitement des sols avec les matériaux locaux pour réduire les coûts.","tags":["Fondations","Talus","Traitement des sols"]},{"icon":4,"title":"Routes & chaussées","description":"Conception, réhabilitation et entretien de routes rurales et urbaines, drainage et assainissement.","tags":["Dimensionnement","Réhabilitation","Drainage"]},{"icon":5,"title":"Barrages & hydraulique","description":"Réhabilitation de digues et déversoirs, choix des matériaux de remblai, curage et protection des berges.","tags":["Digues","Déversoirs","Retenues"]},{"icon":2,"title":"Contrôle qualité & chantier","description":"Suivi des travaux, contrôle des matériaux et du compactage, validation avec les missions de contrôle.","tags":["CBR","Proctor","Réception"]},{"icon":6,"title":"Assistance à maîtrise d'ouvrage","description":"Formulation de projets, suivi-évaluation et coordination avec les partenaires techniques et financiers.","tags":["AMO","Suivi-évaluation","Bailleurs"]}]},"projects":{"title":"Références","text":"Des projets menés pour des maîtres d'ouvrage publics, des bailleurs et des universités, au Togo, au Burkina Faso, en Côte d'Ivoire et au Japon.","linkLabel":"En savoir plus","items":[{"id":"cacao","title":"Programme CACAO — Corridors de croissance","period":"2024 — aujourd'hui","place":"JICA · Togo, Burkina Faso, Côte d'Ivoire","description":"Coordination régionale du plan directeur des corridors de l'anneau de croissance en Afrique de l'Ouest : transport, urbanisme et mobilité, en lien avec les États et l'UEMOA.","tags":["AMO","Multi-pays","Planification"]},{"id":"rural-roads","title":"Réhabilitation de 4 000 km de routes rurales","period":"2020 — 2023","place":"Ministère de l'Agriculture · Togo","description":"Dossiers d'exécution, métrés et devis, puis supervision des terrassements et du compactage avec les missions de contrôle.","tags":["Routes","Métrés & devis","Supervision"]},{"id":"kangounou","title":"Réhabilitation du barrage de Kangounou","period":"2018 — 2019","place":"Kountoire, Togo","description":"Digue et déversoir remis en état : topographie, choix des remblais locaux, stabilisation des talus et curage pour restaurer la retenue.","tags":["Barrage","Talus","Curage"]},{"id":"urban-roads","title":"Voiries urbaines et couches de chaussée","period":"2013","place":"CECO BTP · Lomé, Togo","description":"Suivi des terrassements, mise en œuvre des couches de fondation, de base et de roulement, contrôle des matériaux.","tags":["Voirie","Enrobés","Contrôle qualité"]},{"id":"laterite","title":"Valorisation des sols latéritiques","period":"2014 — 2015","place":"LEMHaB — 2iE, Burkina Faso","description":"Caractérisation des latérites (granulométrie, Atterberg, CBR) pour les utiliser en couches de chaussée et réduire le recours aux matériaux importés.","tags":["Latérite","CBR","Matériaux locaux"]},{"id":"phd","title":"Liant bas carbone à base de cendres recyclées","period":"2020 — 2023","place":"Université Nationale de Yokohama, Japon","description":"Mise au point d'un stabilisant issu de cendres de boues papetières pour renforcer les remblais autour des réseaux enterrés, publié chez Elsevier.","tags":["Innovation","Économie circulaire","Publication"]},{"id":"liquefaction","title":"Remblais résistants aux séismes","period":"2023 — 2024","place":"Université Nationale de Yokohama, Japon","description":"Essais triaxiaux et solutions de stabilisation contre la liquéfaction, avec encadrement d'une équipe d'étudiants.","tags":["Triaxial","Liquéfaction","Encadrement"]}]},"marquee":["Études géotechniques","Fondations","Routes","Barrages","Contrôle qualité","Matériaux locaux","Assistance à maîtrise d'ouvrage","Afrique de l'Ouest"],"experience":{"title":"Parcours","text":"Plus de huit ans entre bureaux d'études, chantiers, laboratoires et coopération internationale.","items":[{"period":"2024 — aujourd'hui","role":"Consultant en infrastructures et développement régional","organization":"JICA — Agence japonaise de coopération internationale","location":"Abidjan, Côte d'Ivoire","highlights":["Coordination de projets de routes, corridors et mobilité urbaine au Togo, au Burkina Faso et en Côte d'Ivoire.","Gestion technique et financière : formulation, suivi et évaluation.","Coordination avec les partenaires régionaux, dont l'UEMOA."]},{"period":"2023 — 2024","role":"Chercheur assistant en innovation urbaine","organization":"Université Nationale de Yokohama","location":"Yokohama, Japon","highlights":["Essais triaxiaux et études de stabilisation contre la liquéfaction.","Formation et encadrement des étudiants aux méthodes d'essais géotechniques."]},{"period":"2020 — 2023","role":"Doctorant — ingénieur géotechnicien","organization":"Université Nationale de Yokohama","location":"Yokohama, Japon","highlights":["Stabilisation des sols pour améliorer la résistance à la liquéfaction autour des conduites enterrées.","Développement de stabilisants à base de cendres pour renforcer les remblais."]},{"period":"2015 — 2020","role":"Ingénieur génie civil — routes et terrassements","organization":"EDF — Entreprise Djantchieme et Formation","location":"Dapaong, Togo","highlights":["Supervision des terrassements, du nivellement et du compactage.","Entretien de 20,3 km de routes rurales et ouvrages hydrauliques (dalots, caniveaux).","Curage de retenues d'eau pour l'agriculture et l'élevage."]},{"period":"2013 — 2015","role":"Stages en laboratoire et en entreprise","organization":"LEMHaB-2iE · CECO BTP · CECO TDE","location":"Ouagadougou & Lomé","highlights":["Essais d'identification et mécaniques des sols (granulométrie, Atterberg, CBR, SPT).","Couches de fondation en sable limoneux traité au ciment, enrobés et réseaux d'eau."]}]},"research":{"title":"Expertise scientifique","text":"Une expertise validée par des publications internationales et reconnue par la JICA.","publicationsTitle":"Publications","publications":[{"year":"2022","title":"Swelling and strength characteristics of sand treated with paper sludge ash-based stabilizer","venue":"Construction and Building Materials (Elsevier), 341, 127849","href":"https://doi.org/10.1016/j.conbuildmat.2022.127849"},{"year":"2023","title":"Effects of dry-wet cycles on the mechanical properties of sand treated with a paper sludge ash-based stabilizer","venue":"9th International Congress on Environmental Geotechnics, Grèce"},{"year":"2021","title":"Fundamental study on the mechanical characteristics of sand treated by a PS ash-based improving material","venue":"Advances in Sustainable Construction and Resource Management (Springer), p. 107-116"},{"year":"Accepté","title":"Normal and seismic characteristics of fill sand improved with biomass waste-derived materials","venue":"Remblais sous chaussées et fondations"}],"distinctionsTitle":"Distinctions & certifications","distinctions":[{"year":"JICA","title":"Certificat d'excellence","issuer":"Agence japonaise de coopération internationale"},{"year":"2020","title":"Prix de la meilleure présentation","issuer":"CREST 2020"},{"year":"2019","title":"Participation à la TICAD 7","issuer":"Ministère des Affaires étrangères du Japon"},{"year":"2018","title":"Programme JICA-DSP & initiative ABE","issuer":"JICA"}],"membershipsTitle":"Membre de","memberships":["JGS — Société japonaise de géotechnique","JSCE — Société japonaise des ingénieurs civils","ONIT — Ordre national des ingénieurs du Togo"],"readLabel":"Lire l'article"},"education":{"title":"Formation & compétences","text":"Un double ancrage académique, entre le Japon et l'Institut 2iE de Ouagadougou.","degrees":[{"year":"2023","title":"Doctorat en ingénierie — géotechnique et géo-environnement","school":"Université Nationale de Yokohama, Japon"},{"year":"2020","title":"Master of Engineering — géotechnique et innovation urbaine","school":"Université Nationale de Yokohama, Japon"},{"year":"2018","title":"Master en conception de routes et d'infrastructures","school":"Institut international 2iE, Burkina Faso"},{"year":"2015","title":"Licence en génie civil","school":"Institut international 2iE, Burkina Faso"}],"languagesTitle":"Langues","languages":[{"name":"Français","level":"Courant","value":100},{"name":"Anglais","level":"Professionnel","value":90},{"name":"Japonais","level":"B2","value":65},{"name":"Moba, haoussa, éwé","level":"Conversation","value":55}],"softwareTitle":"Logiciels","software":["PLAXIS","GeoStudio","AutoCAD Civil 3D","QGIS","Alizé","RDM6","Origin","Fusion 360","MS Project","OpenProject","Microsoft Office"]},"contact":{"title":"Un projet d'infrastructure en tête ?","text":"Étude géotechnique, fondations, routes, barrages ou collaboration de recherche : écrivez-moi, je réponds rapidement.","formTitle":"Envoyer un message","formText":"Présentez votre projet en quelques lignes.","name":"Nom complet","namePlaceholder":"Votre nom","email":"Adresse e-mail","emailPlaceholder":"vous@exemple.com","subject":"Objet","subjects":["Expertise géotechnique","Routes & chaussées","Barrages & hydraulique","Recherche & collaboration","Autre demande"],"message":"Message","messagePlaceholder":"Décrivez votre besoin…","submit":"Envoyer","sending":"Envoi en cours…","success":"Merci ! Votre message a bien été envoyé.","error":"L'envoi a échoué. Réessayez ou écrivez-moi directement par e-mail.","location":"Basé à Abidjan, disponible en Afrique de l'Ouest et à l'international"},"footer":{"title":"Bâtir sur des fondations solides.","text":"Disponible pour des missions d'expertise, de conseil et des collaborations de recherche. Écrivez-moi à tout moment.","rights":"Tous droits réservés.","backToTop":"Retour en haut"},"notFound":{"title":"Page introuvable","text":"Cette page n'existe pas ou a été déplacée.","back":"Retour à l'accueil"}}$json$::jsonb),
  ('en', $json${"meta":{"title":"Dr Maliki Djandjieme — Geotechnical & Infrastructure Consulting Engineer","description":"Geotechnical and infrastructure consulting engineer (PhD, Yokohama). Ground investigations, foundations, roads, dams and site supervision for project owners, design offices and donors across West Africa.","keywords":["geotechnical engineer","geotechnical investigation","foundations","roads","dams","quality control","owner's engineer","Ivory Coast","Togo","Burkina Faso"]},"nav":{"items":[{"id":"home","label":"Home"},{"id":"about","label":"About"},{"id":"services","label":"Services"},{"id":"projects","label":"Track record"},{"id":"experience","label":"Experience"},{"id":"education","label":"Education"},{"id":"research","label":"Research"},{"id":"contact","label":"Contact"}],"openMenu":"Open menu","closeMenu":"Close menu","toggleTheme":"Toggle theme","language":"Language","skip":"Skip to content","menuContactTitle":"Have an infrastructure project in mind?","menuContactText":"Soil investigation, foundations, roads or dams: let's talk about your project.","follow":"Follow me"},"hero":{"kicker":"Consulting engineer · Geotechnics & Infrastructure","headline":"Solid infrastructure, from the ground up.","name":"Dr Maliki Djandjieme","role":"PhD in geotechnical engineering.","intro":"I help project owners, design offices and donors design, control and deliver roads, dams and foundations across West Africa.","badge":"Available for new assignments","cta":"Discuss your project","cv":"Download CV","photoAlt":"Portrait of Dr Maliki Djandjieme at his desk","cardTitle":"PhD · Yokohama","cardText":"JICA consultant","proof":[{"value":"8+","label":"years of experience"},{"value":"4,000 km","label":"of roads supervised"},{"value":"3","label":"countries of work"},{"value":"JICA","label":"infrastructure consultant"}]},"partnersLabel":"Institutions and partners","about":{"title":"About me","text":"A civil engineer specialised in geotechnics, I de-risk your projects from the design stage: well-understood ground means safer structures, controlled costs and fewer surprises on site.","yearsValue":"8+","yearsLabel":"Years of experience","statement":"From the laboratory to the construction site, I combine scientific rigour with field pragmatism to deliver reliable, cost-effective solutions that make the most of local materials.","cta":"Discuss your project","cv":"Download CV","photoAlt":"Maliki Djandjieme outdoors, holding his diploma","portraitAlt":"Portrait of Maliki Djandjieme","stats":[{"value":"4","label":"countries of experience"},{"value":"FR · EN · JA","label":"working languages"},{"value":"UEMOA","label":"regional coordination"}]},"services":{"kicker":"Services","lead":"Reliable, cost-effective solutions suited to the ground.","text":"A complete offer to secure your projects, from ground investigation to handover of the works.","title":"Services.","items":[{"icon":1,"title":"Geotechnical studies","description":"Site investigations, laboratory and in-situ testing, soil reports and design recommendations.","tags":["Boreholes","Lab testing","Reports"]},{"icon":3,"title":"Foundations & earthworks","description":"Foundation design, slope stability and soil treatment with local materials to reduce costs.","tags":["Foundations","Slopes","Soil treatment"]},{"icon":4,"title":"Roads & pavements","description":"Design, rehabilitation and maintenance of rural and urban roads, drainage and stormwater systems.","tags":["Pavement design","Rehabilitation","Drainage"]},{"icon":5,"title":"Dams & hydraulics","description":"Rehabilitation of embankments and spillways, fill material selection, dredging and bank protection.","tags":["Embankments","Spillways","Reservoirs"]},{"icon":2,"title":"Quality control & site supervision","description":"Works supervision, material and compaction control, sign-off with the control missions.","tags":["CBR","Proctor","Handover"]},{"icon":6,"title":"Owner's engineer","description":"Project formulation, monitoring and evaluation, and coordination with technical and financial partners.","tags":["Owner's engineer","M&E","Donors"]}]},"projects":{"title":"Track record","text":"Projects delivered for public owners, donors and universities in Togo, Burkina Faso, Côte d'Ivoire and Japan.","linkLabel":"Learn more","items":[{"id":"cacao","title":"CACAO programme — Growth corridors","period":"2024 — present","place":"JICA · Togo, Burkina Faso, Côte d'Ivoire","description":"Regional coordination of the corridor master plan for the West Africa Growth Ring: transport, urban planning and mobility, working with governments and UEMOA.","tags":["Owner's engineer","Multi-country","Planning"]},{"id":"rural-roads","title":"Rehabilitation of 4,000 km of rural roads","period":"2020 — 2023","place":"Ministry of Agriculture · Togo","description":"Execution files, quantities and cost estimates, then supervision of earthworks and compaction alongside the control missions.","tags":["Roads","Quantities & estimates","Supervision"]},{"id":"kangounou","title":"Kangounou dam rehabilitation","period":"2018 — 2019","place":"Kountoire, Togo","description":"Embankment and spillway restored: topographic surveys, local fill selection, slope stabilization and dredging to recover storage capacity.","tags":["Dam","Slopes","Dredging"]},{"id":"urban-roads","title":"Urban roads and pavement layers","period":"2013","place":"CECO BTP · Lomé, Togo","description":"Earthworks monitoring, construction of sub-base, base and wearing courses, and material quality control.","tags":["Urban roads","Asphalt","Quality control"]},{"id":"laterite","title":"Making the most of lateritic soils","period":"2014 — 2015","place":"LEMHaB — 2iE, Burkina Faso","description":"Characterization of laterites (grain size, Atterberg, CBR) for use in pavement layers, reducing reliance on imported materials.","tags":["Laterite","CBR","Local materials"]},{"id":"phd","title":"Low-carbon binder from recycled ash","period":"2020 — 2023","place":"Yokohama National University, Japan","description":"Development of a paper-sludge-ash stabilizer to reinforce backfill around buried networks, published by Elsevier.","tags":["Innovation","Circular economy","Publication"]},{"id":"liquefaction","title":"Earthquake-resistant fills","period":"2023 — 2024","place":"Yokohama National University, Japan","description":"Triaxial testing and stabilization solutions against liquefaction, while supervising a team of students.","tags":["Triaxial","Liquefaction","Mentoring"]}]},"marquee":["Geotechnical studies","Foundations","Roads","Dams","Quality control","Local materials","Owner's engineer","West Africa"],"experience":{"title":"Experience","text":"More than eight years across design offices, construction sites, laboratories and international cooperation.","items":[{"period":"2024 — present","role":"Consultant in infrastructure and regional development","organization":"JICA — Japan International Cooperation Agency","location":"Abidjan, Côte d'Ivoire","highlights":["Coordination of road, corridor and urban mobility projects in Togo, Burkina Faso and Côte d'Ivoire.","Technical and financial management: formulation, monitoring and evaluation.","Liaison with regional stakeholders, including UEMOA."]},{"period":"2023 — 2024","role":"Assistant researcher in urban innovation","organization":"Yokohama National University","location":"Yokohama, Japan","highlights":["Triaxial tests and soil stabilization studies against liquefaction.","Training and supervision of students on geotechnical testing methods."]},{"period":"2020 — 2023","role":"PhD candidate — geotechnical engineer","organization":"Yokohama National University","location":"Yokohama, Japan","highlights":["Soil stabilization to improve liquefaction resistance around buried pipelines.","Development of ash-based stabilizers to reinforce embankments."]},{"period":"2015 — 2020","role":"Civil engineer — roads and earthworks","organization":"EDF — Djantchieme Company and Worker Training","location":"Dapaong, Togo","highlights":["Supervision of earthworks, levelling and compaction.","Maintenance of 20.3 km of rural roads and hydraulic structures (culverts, gutters).","Dredging of reservoirs for agriculture and livestock."]},{"period":"2013 — 2015","role":"Laboratory and company internships","organization":"LEMHaB-2iE · CECO BTP · CECO TDE","location":"Ouagadougou & Lomé","highlights":["Soil identification and mechanical tests (grain size, Atterberg, CBR, SPT).","Cement-stabilized silty sand sub-bases, asphalt surfacing and water networks."]}]},"research":{"title":"Scientific expertise","text":"Expertise backed by international publications and recognised by JICA.","publicationsTitle":"Publications","publications":[{"year":"2022","title":"Swelling and strength characteristics of sand treated with paper sludge ash-based stabilizer","venue":"Construction and Building Materials (Elsevier), 341, 127849","href":"https://doi.org/10.1016/j.conbuildmat.2022.127849"},{"year":"2023","title":"Effects of dry-wet cycles on the mechanical properties of sand treated with a paper sludge ash-based stabilizer","venue":"9th International Congress on Environmental Geotechnics, Greece"},{"year":"2021","title":"Fundamental study on the mechanical characteristics of sand treated by a PS ash-based improving material","venue":"Advances in Sustainable Construction and Resource Management (Springer), pp. 107-116"},{"year":"Accepted","title":"Normal and seismic characteristics of fill sand improved with biomass waste-derived materials","venue":"Fills under pavements and foundations"}],"distinctionsTitle":"Awards & certifications","distinctions":[{"year":"JICA","title":"Certificate of excellence","issuer":"Japan International Cooperation Agency"},{"year":"2020","title":"Best presentation award","issuer":"CREST 2020"},{"year":"2019","title":"Participation in TICAD 7","issuer":"Ministry of Foreign Affairs of Japan"},{"year":"2018","title":"JICA-DSP programme & ABE Initiative","issuer":"JICA"}],"membershipsTitle":"Member of","memberships":["JGS — Japanese Geotechnical Society","JSCE — Japan Society of Civil Engineers","ONIT — National Order of Engineers of Togo"],"readLabel":"Read the paper"},"education":{"title":"Education & skills","text":"A dual academic grounding, between Japan and the 2iE Institute in Ouagadougou.","degrees":[{"year":"2023","title":"PhD in Engineering — geotechnics and geo-environment","school":"Yokohama National University, Japan"},{"year":"2020","title":"Master of Engineering — geotechnics and urban innovation","school":"Yokohama National University, Japan"},{"year":"2018","title":"Master's degree in road and infrastructure design","school":"2iE International Institute, Burkina Faso"},{"year":"2015","title":"Bachelor of Civil Engineering","school":"2iE International Institute, Burkina Faso"}],"languagesTitle":"Languages","languages":[{"name":"French","level":"Fluent","value":100},{"name":"English","level":"Professional","value":90},{"name":"Japanese","level":"B2","value":65},{"name":"Moba, Hausa, Ewe","level":"Conversational","value":55}],"softwareTitle":"Software","software":["PLAXIS","GeoStudio","AutoCAD Civil 3D","QGIS","Alizé","RDM6","Origin","Fusion 360","MS Project","OpenProject","Microsoft Office"]},"contact":{"title":"Have an infrastructure project in mind?","text":"Geotechnical study, foundations, roads, dams or a research collaboration: write to me, I reply quickly.","formTitle":"Send a message","formText":"Tell me about your project in a few lines.","name":"Full name","namePlaceholder":"Your name","email":"Email address","emailPlaceholder":"you@example.com","subject":"Subject","subjects":["Geotechnical expertise","Roads & pavements","Dams & hydraulics","Research & collaboration","Other request"],"message":"Message","messagePlaceholder":"Describe your needs…","submit":"Send","sending":"Sending…","success":"Thank you! Your message has been sent.","error":"Sending failed. Please try again or email me directly.","location":"Based in Abidjan, available across West Africa and internationally"},"footer":{"title":"Building on solid ground.","text":"Available for expert assignments, consulting and research collaborations. Feel free to reach out anytime.","rights":"All rights reserved.","backToTop":"Back to top"},"notFound":{"title":"Page not found","text":"This page does not exist or has been moved.","back":"Back to home"}}$json$::jsonb),
